import React, { useState } from 'react';
import styled from 'styled-components';

// Styled components for the page layout and form
const Container = styled.div`
  width: 80%;
  margin: 40px auto;
  padding: 20px;
  background-color: #f9f9f9;
  border-radius: 8px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
`;

const Title = styled.h1`
  text-align: center;
  font-size: 32px;
  color: #333;
`;

const Form = styled.form`
  display: flex;
  flex-direction: column;
  gap: 20px;
  max-width: 600px;
  margin: 20px auto;
`;

const Label = styled.label`
  font-size: 18px;
  color: #333;
`;

const Input = styled.input`
  padding: 10px;
  font-size: 16px;
  border-radius: 4px;
  border: 1px solid #ddd;
`;

const Select = styled.select`
  padding: 10px;
  font-size: 16px;
  border-radius: 4px;
  border: 1px solid #ddd;
`;

const Button = styled.button`
  padding: 10px 20px;
  font-size: 18px;
  background-color: #4caf50;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color 0.3s;

  &:hover {
    background-color: #45a049;
  }
`;

const ExperimentPage = () => {
  const [experimentName, setExperimentName] = useState('');
  const [experimenter, setExperimenter] = useState('');
  const [experimentCode, setExperimentCode] = useState('');
  const [creationTime, setCreationTime] = useState('');
  const [message, setMessage] = useState('');

  return (
    <Container>
      <Title>Experiment</Title>
      <Form>
        <div>
          <Label htmlFor="experimentName">Tên thí nghiệm</Label>
          <Input
            type="text"
            id="experimentName"
            value={experimentName}
            onChange={(e) => setExperimentName(e.target.value)}
            required
          />
        </div>

        <div>
          <Label htmlFor="experimenter">Người thêm</Label>
          <Select
            id="experimenter"
            value={experimenter}
            onChange={(e) => setExperimenter(e.target.value)}
            required
          >
            <option value="">Chọn người thêm</option>
            <option value="Người 1">Người 1</option>
            <option value="Người 2">Người 2</option>
            <option value="Người 3">Người 3</option>
          </Select>
        </div>

        <div>
          <Label htmlFor="experimentCode">Mã thí nghiệm</Label>
          <Input
            type="text"
            id="experimentCode"
            value={experimentCode}
            onChange={(e) => setExperimentCode(e.target.value)}
            required
          />
        </div>

        <div>
          <Label htmlFor="creationTime">Thời gian tạo</Label>
          <Input
            type="datetime-local"
            id="creationTime"
            value={creationTime}
            onChange={(e) => setCreationTime(e.target.value)}
            required
          />
        </div>

        <Button type="submit">Thêm thí nghiệm</Button>
      </Form>

      {message && <p style={{ textAlign: 'center', color: 'green' }}>{message}</p>}
    </Container>
  );
};

export default ExperimentPage;
